def discard_staged_declaration(db: Any, decree_ref: str) -> int:
    """撤旨 / 改旨作废该旨全部仍暂存的预推产物；返回被作废的条数。已经结算过
    的旨不受影响（ADR 0157：改旨＝作废后按新旨重起，不追改已落账的历史）。"""
    return db.staged_declarations.discard(decree_ref)

def _appointment_region_id(payload: Dict[str, object]) -> str:
    """Typed 任所 from appointment payload keys; never inferred from title/location."""
    return str(
        payload.get("region_id")
        or payload.get("任所")
        or payload.get("辖区")
        or payload.get("office_region")
        or ""
    ).strip()

def _person_change_name(item: Dict[str, object]) -> str:
    return str(
        item.get("name")
        or item.get("姓名")
        or item.get("character")
        or item.get("person")
        or ""
    ).strip()

def validate_delta_shape(extracted: dict) -> None:
    """Validate unsplittable delta shape; split-capable bad items are ADR0015 rejections."""
    sanitize_delta_shape(extracted)

def character_row(name: str):
        return db.conn.execute(
            "SELECT name, status, office, office_type, power_id, status_reason, "
            "status_changed_turn, reason_code, transit_to, transit_distance_remaining, "
            "transit_speed_factor, transit_start_turn "
            "FROM characters WHERE name=?",
            (name,),
        ).fetchone()

def class_rows(self, region_id: str = "") -> List[sqlite3.Row]:
        """region_id="" 取全国汇总行；其它取该省切片。"""
        return self.conn.execute(
            "SELECT name, region_id, population, satisfaction, leverage, agenda "
            "FROM classes WHERE region_id = ? ORDER BY name",
            (region_id,),
        ).fetchall()

def get_directive(self, directive_id: int) -> Optional[sqlite3.Row]:
        """按 id 读单条 turn_directives（#1769 补交读口；禁 session 手写 SELECT）。"""
        return self.conn.execute(
            "SELECT id, text, status, turn, dossier_payload_json "
            "FROM turn_directives WHERE id=?",
            (int(directive_id),),
        ).fetchone()

def list_closed_issues_at(self, closed_turn: int) -> List[sqlite3.Row]:
        """指定 turn 关闭（resolved / failed / dropped）的 issue。"""
        return self.conn.execute(
            "SELECT * FROM issues WHERE closed_turn = ? AND status IN ('resolved','failed','dropped') ORDER BY id",
            (int(closed_turn),),
        ).fetchall()

def find_active_issue_by_origin(self, origin_kind: str, origin_ref: str) -> sqlite3.Row | None:
        return self.conn.execute(
            "SELECT * FROM issues WHERE origin_kind=? AND origin_ref=? AND status='active' LIMIT 1",
            (origin_kind, origin_ref),
        ).fetchone()

def find_any_issue_by_origin(self, origin_kind: str, origin_ref: str) -> sqlite3.Row | None:
        """查任意状态（含 resolved/failed/dropped）的同源 issue，用于 spawn 去重。"""
        return self.conn.execute(
            "SELECT * FROM issues WHERE origin_kind=? AND origin_ref=? LIMIT 1",
            (origin_kind, origin_ref),
        ).fetchone()

def list_recent_issue_advances(self, issue_id: int, limit: int = 3) -> List[sqlite3.Row]:
        return self.conn.execute(
            "SELECT * FROM issue_advances WHERE issue_id=? ORDER BY id DESC LIMIT ?",
            (issue_id, limit),
        ).fetchall()

def read_credit_events_as_edges(self, records: Iterable[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """0079 读侧契约适配；只返回边，不把 fixture 写入 0079 或本表。"""
        return credit_events_as_edges(records)

def translation_holding_write_gate(gate: Any) -> bool:
    """该 gate 是否正被转译短持（与所有权同临界可读；不 join、不 cancel）。"""
    return _translation_write_gate(gate).is_held_by_translation()

def wait_translation_write_gate_released(gate: Any) -> None:
    """等到该 gate 不再被转译持有（不抢闸、不加超时；结算/他写不抬此等待）。"""
    _translation_write_gate(gate).wait_while_held_by_translation()

def _issue_row(db: Any, commitment_ref: int) -> Any:
    return db.conn.execute(
        "SELECT * FROM issues WHERE id=?", (int(commitment_ref),),
    ).fetchone()

def investigation_tip_records(db: Any, dossier_id: int) -> List[Dict[str, object]]:
    """4a 供料读口：本案已声明的真实通风报信。"""
    return _tip_records(db, dossier_id)

def derive_denunciation_is_true(*, fork: bool) -> bool:
    """#627 真伪底机械对账：所指案卷真有分叉=真检举，无分叉=私货/诬告。"""
    return bool(fork)

def _cli_process_clock() -> float:
    """CLI 增量读循环的取时点（受控推进用；生产恒 time.monotonic）。"""
    return time.monotonic()

def vacate(self, ticket: Optional[WriteTicket]) -> None:
        """Empty release on fail/cancel — same as complete (order advances)."""
        self.complete(ticket)

def ticketed_gate(self, ticket: WriteTicket) -> TicketedWriteGate:
        """Production write seam for a claimed ticket."""
        return TicketedWriteGate(self, ticket)

def _character_power_id(character: Character, db) -> str:
    """人物所属势力 id：DB 权威，回退内存 power_id，默认 ming。

    权威解析单一真源在 db.resolve_power_id（session.can_summon 等同源复用，见 #125），
    此处委托，朝堂可见性/召见两端口径一致、不各写一份。"""
    return db.resolve_power_id(character)

def _complete_pending_write(self, ticket: Optional[WriteTicket] = None) -> None:
        """释放领票（成功/失败/空放行同形）。"""
        self._runtime_write_queue().complete(ticket)

def interrupted_reply_retries(self, minister_name: str) -> List[Dict[str, Any]]:
        """#505：某大臣重开后待重试的中断回话轮（问话已落、回话未落）——恢复提示取数。"""
        return self.db.get_interrupted_reply_retries(minister_name)
